output_text:
[
  {
    "id": "no_cart_single_file_aisle",
    "text": "Shopping carts are prohibited in single-file shelf aisles where shelves flank both sides and the horizontal free width is one cell.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_enter_single_file_with_cart",
    "text": "Agents must not push a cart across the threshold into a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": "hasCart",
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "no_walking_cartless_except_service_aisle",
    "text": "After taking a cart, agents may walk without it only during a short on-foot excursion in a single-file shelf aisle or its mouth.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "aisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "cartlessPedestrianZone": {
          "or": [
            "singleFileShelfAisle",
            "aisleMouth"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": "cartlessPedestrianZone"
          }
        ]
      }
    }
  },
  {
    "id": "recover_cart_after_parking",
    "text": "Whenever an agent parks a cart at the mouth of a narrow shelf aisle, they are obliged to recover it before leaving the store.",
    "abstraction": {
      "state_properties": {
        "aisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "cartParkedAtMouth": {
          "pre": {
            "and": [
              "aisleMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "cartRecoveredAtMouth": {
          "pre": {
            "and": [
              "aisleMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartParkedAtMouth",
      "discharge": "cartRecoveredAtMouth"
    }
  },
  {
    "id": "single_file_shelf_pick_on_foot",
    "text": "Shelf interactions inside single-file shelf aisles must be performed on foot, without holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "singleFileShelfInteraction": {
          "pre": {
            "and": [
              "INTERACT",
              "singleFileShelfAisle"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "singleFileShelfInteraction",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "wide_shelf_pick_with_cart",
    "text": "At shelf faces in wide aisles, agents should interact with the shelf while still having their cart.",
    "abstraction": {
      "state_properties": {
        "wideShelfFace": {
          "and": [
            "adjShelf",
            {
              "gt": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "wideShelfInteraction": {
          "pre": {
            "and": [
              "INTERACT",
              "wideShelfFace"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "wideShelfInteraction",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "cart_required_in_open_travel_aisles",
    "text": "In broad open travel aisles, agents are prohibited from moving around without their cart, except at a narrow-aisle mouth where the cart is being parked or retrieved.",
    "abstraction": {
      "state_properties": {
        "openTravelAisle": {
          "ge": [
            "freeWidthH",
            6
          ]
        },
        "aisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          "openTravelAisle",
          {
            "not": "aisleMouth"
          },
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "return_to_cart_after_single_file_excursion",
    "text": "Once an agent enters a single-file shelf aisle without a cart, they are obliged to return to and regain the cart before exiting.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "aisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "onFootInSingleFileAisle": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": null
        },
        "cartRecoveredAtMouth": {
          "pre": {
            "and": [
              "aisleMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "onFootInSingleFileAisle",
      "discharge": "cartRecoveredAtMouth"
    }
  }
]
